import '../client/result_mapper.dart';
import '../json.dart';

/// An operation with its variables and the parser for its data, as
/// generated by `dart run graphql_client_flutter:generate`.
///
/// Pass it to `GraphQLQuery.operation` or `GraphQLSubscription.operation`
/// to get typed data without repeating the document, variables and parser:
///
/// ```dart
/// GraphQLQuery.operation(
///   getUserOperation(id: '1'),
///   builder: (context, state, query) => ...,
/// )
/// ```
final class TypedOperation<T> {
  /// Creates an operation.
  const TypedOperation({
    required this.document,
    required this.parse,
    this.variables = const {},
  });

  /// The GraphQL document.
  final String document;

  /// The variables, as JSON.
  final JsonMap variables;

  /// Converts the result data to [T].
  final DataParser<T> parse;
}
